더 긴 Java 코드 예시입니다.

```java
import java.util.ArrayList;
import java.util.List;

record Expense(String title, String category, double amount) {}

class ExpenseRepository {
    private final List<Expense> expenses = new ArrayList<>();
    void add(Expense expense) { expenses.add(expense); }
    double total() { return expenses.stream().mapToDouble(Expense::amount).sum(); }
    List<Expense> byCategory(String category) {
        return expenses.stream().filter(item -> item.category().equals(category)).toList();
    }
}

public class SmartSpend {
    public static void main(String[] args) {
        ExpenseRepository repository = new ExpenseRepository();
        repository.add(new Expense("Lunch", "Food", 12.5));
        System.out.println(repository.total());
    }
}
```

전체 예시는 /java-very-long에서 확인하세요.

Repository와 Service 구조를 보여주는 Java 예시입니다.

```java
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

record Expense(long id, String title, String category, double amount) {}

final class ExpenseRepository {
    private final List<Expense> expenses = new ArrayList<>();
    void add(Expense expense) { expenses.add(expense); }
    void remove(long id) { expenses.removeIf(item -> item.id() == id); }
    List<Expense> findAll() { return List.copyOf(expenses); }
}

final class ExpenseService {
    private final ExpenseRepository repository;
    ExpenseService(ExpenseRepository repository) { this.repository = repository; }
    Map<String, Double> totalsByCategory() {
        return repository.findAll().stream().collect(Collectors.groupingBy(
            Expense::category, Collectors.summingDouble(Expense::amount)));
    }
}

public class SmartSpend {
    public static void main(String[] args) {
        ExpenseRepository repository = new ExpenseRepository();
        repository.add(new Expense(1, "Lunch", "Food", 12.5));
        repository.add(new Expense(2, "Bus", "Transport", 2.0));
        ExpenseService service = new ExpenseService(repository);
        service.totalsByCategory().forEach((category, total) ->
            System.out.println(category + ": " + total));
    }
}
```

더 긴 C 코드 예시입니다.

```c
#include <stdio.h>

#define MAX_EXPENSES 32

typedef struct {
    char title[64];
    char category[32];
    double amount;
} Expense;

double total(const Expense expenses[], size_t count) {
    double result = 0.0;
    for (size_t i = 0; i < count; ++i) result += expenses[i].amount;
    return result;
}

int main(void) {
    Expense expenses[MAX_EXPENSES] = {
        {"Lunch", "Food", 12.5},
        {"Bus", "Transport", 2.0}
    };
    printf("Total: %.2f\n", total(expenses, 2));
    return 0;
}
```

전체 예시는 /c-very-long에서 확인하세요.

작은 Repository 형태의 데이터 흐름을 보여주는 C 예시입니다.

```c
#include <stdio.h>
#include <string.h>

#define MAX_EXPENSES 64

typedef struct {
    int id;
    char title[64];
    char category[32];
    double amount;
} Expense;

typedef struct {
    Expense items[MAX_EXPENSES];
    size_t count;
} ExpenseRepository;

void add_expense(ExpenseRepository* repository, Expense expense) {
    if (repository->count < MAX_EXPENSES) repository->items[repository->count++] = expense;
}

double total_by_category(const ExpenseRepository* repository, const char* category) {
    double total = 0.0;
    for (size_t i = 0; i < repository->count; ++i)
        if (strcmp(repository->items[i].category, category) == 0) total += repository->items[i].amount;
    return total;
}

int main(void) {
    ExpenseRepository repository = {0};
    add_expense(&repository, (Expense){1, "Lunch", "Food", 12.5});
    add_expense(&repository, (Expense){2, "Coffee", "Food", 4.5});
    printf("Food total: %.2f\n", total_by_category(&repository, "Food"));
    return 0;
}
```

더 긴 C++ 코드 예시입니다.

```cpp
#include <iostream>
#include <numeric>
#include <string>
#include <vector>

struct Expense {
    std::string title;
    std::string category;
    double amount;
};

class ExpenseRepository {
public:
    void add(Expense expense) { expenses.push_back(std::move(expense)); }
    double total() const {
        return std::accumulate(expenses.begin(), expenses.end(), 0.0,
            [](double sum, const Expense& item) { return sum + item.amount; });
    }
private:
    std::vector<Expense> expenses;
};

int main() {
    ExpenseRepository repository;
    repository.add({"Lunch", "Food", 12.5});
    repository.add({"Bus", "Transport", 2.0});
    std::cout << "Total: " << repository.total() << std::endl;
}
```

전체 예시는 /cpp-very-long에서 확인하세요.

표준 라이브러리를 사용하는 C++ Service 예시입니다.

```cpp
#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <vector>

struct Expense {
    int id;
    std::string title;
    std::string category;
    double amount;
};

class ExpenseRepository {
public:
    void add(Expense expense) { expenses.push_back(std::move(expense)); }
    void remove(int id) {
        expenses.erase(std::remove_if(expenses.begin(), expenses.end(),
            [id](const Expense& item) { return item.id == id; }), expenses.end());
    }
    const std::vector<Expense>& all() const { return expenses; }
private:
    std::vector<Expense> expenses;
};

class ExpenseService {
public:
    explicit ExpenseService(ExpenseRepository& repository) : repository(repository) {}
    std::map<std::string, double> summary() const {
        std::map<std::string, double> result;
        for (const auto& item : repository.all()) result[item.category] += item.amount;
        return result;
    }
private:
    ExpenseRepository& repository;
};

int main() {
    ExpenseRepository repository;
    repository.add({1, "Lunch", "Food", 12.5});
    repository.add({2, "Bus", "Transport", 2.0});
    ExpenseService service(repository);
    for (const auto& [category, total] : service.summary())
        std::cout << category << ": " << total << std::endl;
}
```

코틀린 코드 예시입니다.

```kotlin
data class Expense(
    val title: String,
    val category: String,
    val amount: Double
)

class ExpenseRepository {
    private val expenses = mutableListOf<Expense>()

    fun add(expense: Expense) {
        expenses += expense
    }

    fun remove(title: String) {
        expenses.removeAll { it.title == title }
    }

    fun total(): Double = expenses.sumOf { it.amount }

    fun byCategory(category: String): List<Expense> =
        expenses.filter { it.category == category }
}

val repository = ExpenseRepository()
repository.add(Expense("Lunch", "Food", 12.5))
repository.add(Expense("Bus", "Transport", 2.0))
println(repository.byCategory("Food"))
println("Total = ${repository.total()}")
```

더 자세한 예시는 /kotlin-very-long에서 확인하세요.

실제 앱 구조를 간단히 보여주는 Kotlin 예시입니다.

```kotlin
data class Expense(
    val id: Long,
    val title: String,
    val category: String,
    val amount: Double,
    val createdAt: Long = System.currentTimeMillis()
)

class ExpenseRepository {
    private val expenses = mutableListOf<Expense>()

    fun add(expense: Expense) {
        expenses += expense
    }

    fun remove(id: Long) {
        expenses.removeAll { it.id == id }
    }

    fun observeAll(): List<Expense> = expenses.toList()

    fun total(): Double = expenses.sumOf { it.amount }

    fun totalByCategory(category: String): Double =
        expenses.filter { it.category == category }.sumOf { it.amount }
}

class ExpenseViewModel(private val repository: ExpenseRepository) {
    fun addExpense(title: String, category: String, amount: Double) {
        repository.add(Expense(System.currentTimeMillis(), title, category, amount))
    }

    fun summary(): Map<String, Double> =
        repository.observeAll().groupBy { it.category }
            .mapValues { (_, items) -> items.sumOf { it.amount } }
}

fun main() {
    val repository = ExpenseRepository()
    val viewModel = ExpenseViewModel(repository)
    viewModel.addExpense("Lunch", "Food", 12.5)
    viewModel.addExpense("Bus", "Transport", 2.0)
    viewModel.addExpense("Coffee", "Food", 4.5)

    viewModel.summary().forEach { (category, total) ->
        println("$category: $total")
    }
    println("Total: ${repository.total()}")
}
```

더 긴 Python 코드 예시입니다.

```python
from dataclasses import dataclass

@dataclass
class Expense:
    title: str
    category: str
    amount: float

class ExpenseRepository:
    def __init__(self) -> None:
        self.expenses: list[Expense] = []

    def add(self, expense: Expense) -> None:
        self.expenses.append(expense)

    def total(self) -> float:
        return sum(item.amount for item in self.expenses)

    def by_category(self, category: str) -> list[Expense]:
        return [item for item in self.expenses if item.category == category]

repository = ExpenseRepository()
repository.add(Expense("Lunch", "Food", 12.5))
repository.add(Expense("Bus", "Transport", 2.0))
print(repository.by_category("Food"))
print(f"Total = {repository.total()}")
```

더 자세한 예시는 /python-very-long에서 확인하세요.

실제 앱 구조를 보여주는 Python 예시입니다.

```python
from dataclasses import dataclass, field
from collections import defaultdict

@dataclass
class Expense:
    id: int
    title: str
    category: str
    amount: float

@dataclass
class ExpenseRepository:
    expenses: list[Expense] = field(default_factory=list)

    def add(self, expense: Expense) -> None:
        self.expenses.append(expense)

    def remove(self, expense_id: int) -> None:
        self.expenses = [item for item in self.expenses if item.id != expense_id]

    def total(self) -> float:
        return sum(item.amount for item in self.expenses)

    def totals_by_category(self) -> dict[str, float]:
        totals: dict[str, float] = defaultdict(float)
        for item in self.expenses:
            totals[item.category] += item.amount
        return dict(totals)

class ExpenseService:
    def __init__(self, repository: ExpenseRepository) -> None:
        self.repository = repository

    def add_expense(self, title: str, category: str, amount: float) -> None:
        next_id = len(self.repository.expenses) + 1
        self.repository.add(Expense(next_id, title, category, amount))

    def print_summary(self) -> None:
        for category, total in self.repository.totals_by_category().items():
            print(f"{category}: {total:.2f}")
        print(f"Total: {self.repository.total():.2f}")

repository = ExpenseRepository()
service = ExpenseService(repository)
service.add_expense("Lunch", "Food", 12.5)
service.add_expense("Bus", "Transport", 2.0)
service.add_expense("Coffee", "Food", 4.5)
service.print_summary()
```

